import type { Locale } from "./i18n";

export type LegalLocale = "en" | "tr";
export type ExtendedLocale = "en" | "tr" | "ru" | "de" | "es" | "ja" | "zh" | "el" | "bg" | "sr" | "ko" | "it" | "hr" | "fr" | "ro" | "ar" | "nl" | "pl" | "uk" | "id" | "pt";
export type HelpLocale = ExtendedLocale;

export function legalLocale(l: Locale): LegalLocale {
  return l === "tr" ? "tr" : "en";
}

export function extendedLocale(l: Locale): ExtendedLocale {
  const supported: ExtendedLocale[] = ["en", "tr", "ru", "de", "es", "ja", "zh", "el", "bg", "sr", "ko", "it", "hr", "fr", "ro", "ar", "nl", "pl", "uk", "id", "pt"];
  return (supported.includes(l as ExtendedLocale) ? l : "en") as ExtendedLocale;
}

export function helpLocale(l: Locale): HelpLocale {
  return extendedLocale(l);
}

